import { getApiOrigin, formatShopCurrency, DEFAULT_SHOP_CONFIG } from './config';
import { CheckoutItemPayload, CheckoutSuccessResponse } from './shop';

export type PaymentStatus =
  | 'CREATED'
  | 'REDIRECTED'
  | 'VERIFY_PENDING'
  | 'VERIFIED'
  | 'FAILED'
  | 'CANCELED'
  | 'FRAUD'
  | 'REQUEST_UNKNOWN';

export type PaymentConflictCode =
  | 'IDEMPOTENCY_KEY_REUSED'
  | 'ITEM_CHECKOUT_IN_PROGRESS'
  | 'PAYMENT_OUTCOME_UNKNOWN'
  | 'PAYMENT_IN_PROGRESS'
  | 'ORDER_ALREADY_PROCESSED'
  | 'PAYMENT_ALREADY_PROCESSED';

export interface PaymentRecord {
  paymentId: string;
  orderId?: string;
  amount: number;
  currency?: string;
  status: PaymentStatus;
  createdAt?: string;
  verifiedAt?: string;
  refId?: string;
}

export interface OrderRecord {
  _id: string;
  orderId?: string;
  status: 'PENDING' | 'PAID' | 'FAILED' | 'CANCELLED';
  fulfillmentStatus?: 'PENDING' | 'PROCESSING' | 'COMPLETED' | 'FAILED';
  totalAmount: number;
  currency: string;
  items: Array<{
    type: string;
    id: string;
    quantity: number;
    price: number;
    title?: string;
  }>;
  createdAt: string;
}

export interface CreatePaymentPayload {
  amount?: number;
  description?: string;
  items?: CheckoutItemPayload[];
}

export interface CreatePaymentSuccessResponse {
  success: true;
  orderId?: string;
  paymentId: string;
  redirect: string;
  status?: string;
  totalAmount?: number;
  currency?: string;
}

export interface PaymentStatusResponse {
  success: true;
  payment: PaymentRecord;
}

export class PaymentApiError extends Error {
  public readonly status: number;
  public readonly code?: string;
  public readonly paymentId?: string;
  public readonly orderId?: string;

  constructor(message: string, status: number, code?: string, paymentId?: string, orderId?: string) {
    super(message);
    this.name = 'PaymentApiError';
    this.status = status;
    this.code = code;
    this.paymentId = paymentId;
    this.orderId = orderId;
  }
}

export interface CheckoutAttempt {
  idempotencyKey: string;
  cartKey: string;
  amount?: number;
  items?: CheckoutItemPayload[];
  description?: string;
  paymentId?: string;
  orderId?: string;
  lastStatus?: PaymentStatus;
  createdAt: string;
}

const ATTEMPT_STORAGE_KEY = 'quader_checkout_payment_attempt_v2';

/**
 * Terminal failure/canceled statuses after which a new user-initiated attempt
 * must generate a fresh idempotency key.
 */
export function isTerminalFailureStatus(status?: PaymentStatus): boolean {
  return status === 'FAILED' || status === 'CANCELED' || status === 'FRAUD';
}

/**
 * Generates an RFC4122 v4 UUID for the `Idempotency-Key` header.
 */
export function generateIdempotencyKey(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, char => {
    const rand = (Math.random() * 16) | 0;
    const val = char === 'x' ? rand : (rand & 0x3) | 0x8;
    return val.toString(16);
  });
}

/**
 * Formats a currency amount for explicit display on checkout and status screens.
 * Replaces hardcoded assumptions with dynamic backend-configured currency (default: IRR).
 */
export function formatIrrAmount(amount: number, currency: string = DEFAULT_SHOP_CONFIG.currency): string {
  return formatShopCurrency(amount, currency);
}

/**
 * Legacy conversion helper for tests.
 * @deprecated Prices are handled directly in backend-configured currency (IRR/IRT) per Migration Specification.
 */
export function convertUsdToIrr(usdAmount: number, rate = 100): number {
  return Math.round(usdAmount * rate);
}

/**
 * Reads the persisted checkout attempt from sessionStorage.
 */
export function getStoredCheckoutAttempt(): CheckoutAttempt | null {
  if (typeof sessionStorage === 'undefined') return null;
  try {
    const raw = sessionStorage.getItem(ATTEMPT_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as CheckoutAttempt;
    if (!parsed || typeof parsed.idempotencyKey !== 'string' || !parsed.idempotencyKey) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

/**
 * Saves the current checkout attempt in sessionStorage.
 */
export function saveCheckoutAttempt(attempt: CheckoutAttempt): CheckoutAttempt {
  if (typeof sessionStorage !== 'undefined') {
    try {
      sessionStorage.setItem(ATTEMPT_STORAGE_KEY, JSON.stringify(attempt));
    } catch {}
  }
  return attempt;
}

/**
 * Clears the stored checkout attempt (called upon verified payment or explicit reset).
 */
export function clearCheckoutAttempt(): void {
  if (typeof sessionStorage !== 'undefined') {
    try {
      sessionStorage.removeItem(ATTEMPT_STORAGE_KEY);
    } catch {}
  }
}

/**
 * Returns the existing checkout attempt if it matches the current cart items/key and is not
 * in a terminal failure state, or creates and persists a single UUID idempotency key.
 */
export function getOrCreateCheckoutAttempt(params: {
  cartKey: string;
  amount?: number;
  items?: CheckoutItemPayload[];
  description?: string;
}): CheckoutAttempt {
  const existing = getStoredCheckoutAttempt();
  if (
    existing &&
    existing.cartKey === params.cartKey &&
    !isTerminalFailureStatus(existing.lastStatus)
  ) {
    return existing;
  }

  const fresh: CheckoutAttempt = {
    idempotencyKey: generateIdempotencyKey(),
    cartKey: params.cartKey,
    amount: params.amount,
    items: params.items,
    description: params.description,
    createdAt: new Date().toISOString(),
  };
  return saveCheckoutAttempt(fresh);
}

/**
 * Explicitly rotates the idempotency key when the user deliberately initiates
 * a new payment attempt after a terminal failure/cancel or manual retry.
 */
export function startNewCheckoutAttempt(params: {
  cartKey: string;
  amount?: number;
  items?: CheckoutItemPayload[];
  description?: string;
}): CheckoutAttempt {
  const fresh: CheckoutAttempt = {
    idempotencyKey: generateIdempotencyKey(),
    cartKey: params.cartKey,
    amount: params.amount,
    items: params.items,
    description: params.description,
    createdAt: new Date().toISOString(),
  };
  return saveCheckoutAttempt(fresh);
}

export function updateStoredCheckoutAttempt(patch: Partial<CheckoutAttempt>): CheckoutAttempt | null {
  const current = getStoredCheckoutAttempt();
  if (!current) return null;
  const updated: CheckoutAttempt = { ...current, ...patch };
  return saveCheckoutAttempt(updated);
}

export const paymentNavigation = {
  redirectToGateway(url: string): void {
    if (!url || typeof url !== 'string') {
      throw new Error('Invalid gateway redirect URL.');
    }
    window.location.assign(url);
  },
};

function parseErrorPayload(data: any, fallbackStatus: number): {
  message: string;
  code?: string;
  paymentId?: string;
  orderId?: string;
} {
  const code =
    data?.code ||
    data?.errorCode ||
    (typeof data?.error === 'string' && /^[A-Z_]+$/.test(data.error) ? data.error : undefined);
  const paymentId =
    data?.paymentId ||
    data?.payment?.paymentId ||
    data?.payment?._id ||
    data?.data?.paymentId;
  const orderId =
    data?.orderId ||
    data?.order?.orderId ||
    data?.order?._id ||
    data?.order?.id ||
    data?.data?.orderId;
  const message =
    data?.message ||
    (typeof data?.error === 'string' ? data.error : undefined) ||
    `Payment request failed with status ${fallbackStatus}`;
  return { message, code, paymentId, orderId };
}

/**
 * Low-level API calls adhering strictly to the backend payment contract:
 * 1. `POST /api/shop/checkout` (item references, browser credentials, and RFC4122 v4 UUID Idempotency-Key)
 *    NO amount, total, or currency is sent.
 * 2. `GET /api/shop/payments/status/:paymentId` (with fallback to /shop/payments/status/:paymentId)
 * 3. `GET /api/shop/orders/:orderId` (with credentials)
 * 4. `GET /api/shop/library` (with credentials)
 */
export const paymentApi = {
  /**
   * Primary checkout submission calling POST ${VITE_API_URL}/api/shop/checkout:
   * Sends item references and quantities with browser credentials and UUID Idempotency-Key.
   * Does NOT send amount, total, or currency. Prices are calculated by backend from active catalog records.
   */
  async checkout(
    items: CheckoutItemPayload[],
    idempotencyKey: string
  ): Promise<CheckoutSuccessResponse> {
    if (!items || items.length === 0) {
      throw new PaymentApiError('Checkout cart cannot be empty.', 400, 'EMPTY_CART');
    }
    if (!idempotencyKey || !idempotencyKey.trim()) {
      throw new PaymentApiError('Idempotency-Key is required.', 400, 'MISSING_IDEMPOTENCY_KEY');
    }

    // Strictly ensure only item references and quantities are sent (never amount, total, or currency)
    const sanitizedItems = items.map(item => ({
      type: item.type,
      id: item.id,
      quantity: Math.max(1, Number(item.quantity) || 1),
    }));

    const origin = getApiOrigin();
    const res = await fetch(`${origin}/api/shop/checkout`, {
      method: 'POST',
      credentials: 'include',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Idempotency-Key': idempotencyKey.trim(),
      },
      body: JSON.stringify({ items: sanitizedItems }),
    });

    let data: any = null;
    try {
      data = await res.json();
    } catch {
      data = null;
    }

    if (!res.ok || !data?.success) {
      const { message, code, paymentId, orderId } = parseErrorPayload(data, res.status);
      throw new PaymentApiError(message, res.status, code, paymentId, orderId);
    }

    if (typeof data.redirect !== 'string' || !data.redirect.trim()) {
      throw new PaymentApiError(
        'Gateway redirect URL was missing from payment response.',
        502,
        'MISSING_REDIRECT',
        data.paymentId,
        data.orderId
      );
    }

    return {
      success: true,
      orderId: String(data.orderId || ''),
      paymentId: String(data.paymentId || ''),
      status: data.status || 'REDIRECTED',
      totalAmount: Number(data.totalAmount) || 0,
      currency: data.currency || DEFAULT_SHOP_CONFIG.currency,
      redirect: String(data.redirect),
    };
  },

  /**
   * Alias for checkout submission that ensures no caller hits the retired 410 amount-based endpoint.
   * @deprecated Call paymentApi.checkout directly.
   */
  async createPayment(
    payload: CreatePaymentPayload,
    idempotencyKey: string
  ): Promise<CreatePaymentSuccessResponse> {
    if (!idempotencyKey || !idempotencyKey.trim()) {
      throw new PaymentApiError('Idempotency-Key is required.', 400, 'MISSING_IDEMPOTENCY_KEY');
    }

    const items: CheckoutItemPayload[] =
      payload.items && payload.items.length > 0
        ? payload.items
        : [{ type: 'product', id: 'catalog-item', quantity: 1 }];

    const res = await paymentApi.checkout(items, idempotencyKey);
    return {
      success: true,
      orderId: res.orderId,
      paymentId: res.paymentId,
      redirect: res.redirect,
      status: res.status,
      totalAmount: res.totalAmount,
      currency: res.currency,
    };
  },

  async getPaymentStatus(paymentId: string): Promise<PaymentStatusResponse> {
    if (!paymentId || !paymentId.trim()) {
      throw new PaymentApiError('Payment ID is required to check status.', 400, 'MISSING_PAYMENT_ID');
    }

    const origin = getApiOrigin();
    const encodedId = encodeURIComponent(paymentId.trim());

    // Canonical /api/shop/payments/status/:paymentId first, fall back to /shop/payments/status/:paymentId
    let res = await fetch(`${origin}/api/shop/payments/status/${encodedId}`, {
      method: 'GET',
      credentials: 'include',
      headers: { Accept: 'application/json' },
    });

    if (res.status === 404) {
      res = await fetch(`${origin}/shop/payments/status/${encodedId}`, {
        method: 'GET',
        credentials: 'include',
        headers: { Accept: 'application/json' },
      });
    }

    let data: any = null;
    try {
      data = await res.json();
    } catch {
      data = null;
    }

    if (!res.ok || !data?.success || !data?.payment) {
      const { message, code } = parseErrorPayload(data, res.status);
      throw new PaymentApiError(message, res.status, code, paymentId);
    }

    return {
      success: true,
      payment: {
        paymentId: String(data.payment.paymentId || data.payment._id || paymentId),
        orderId: data.payment.orderId ? String(data.payment.orderId) : undefined,
        amount: Number(data.payment.amount),
        currency: data.payment.currency || DEFAULT_SHOP_CONFIG.currency,
        status: data.payment.status as PaymentStatus,
        createdAt: data.payment.createdAt,
        verifiedAt: data.payment.verifiedAt,
        refId: data.payment.refId,
      },
    };
  },

  async getOrder(orderId: string): Promise<OrderRecord> {
    if (!orderId || !orderId.trim()) {
      throw new PaymentApiError('Order ID is required.', 400, 'MISSING_ORDER_ID');
    }
    const origin = getApiOrigin();
    const encodedId = encodeURIComponent(orderId.trim());

    let res = await fetch(`${origin}/api/shop/orders/${encodedId}`, {
      method: 'GET',
      credentials: 'include',
      headers: { Accept: 'application/json' },
    });

    if (res.status === 404) {
      res = await fetch(`${origin}/shop/orders/${encodedId}`, {
        method: 'GET',
        credentials: 'include',
        headers: { Accept: 'application/json' },
      });
    }

    let data: any = null;
    try {
      data = await res.json();
    } catch {
      data = null;
    }

    if (!res.ok) {
      const { message, code } = parseErrorPayload(data, res.status);
      throw new PaymentApiError(message, res.status, code, undefined, orderId);
    }

    const ord = data?.order || data;
    return {
      _id: String(ord._id || ord.orderId || orderId),
      orderId: String(ord.orderId || ord._id || orderId),
      status: ord.status || 'PENDING',
      fulfillmentStatus: ord.fulfillmentStatus || (ord.status === 'PAID' ? 'COMPLETED' : 'PENDING'),
      totalAmount: Number(ord.totalAmount) || 0,
      currency: ord.currency || DEFAULT_SHOP_CONFIG.currency,
      items: Array.isArray(ord.items) ? ord.items : [],
      createdAt: ord.createdAt || new Date().toISOString(),
    };
  },

  async getLibrary(): Promise<any[]> {
    const origin = getApiOrigin();
    let res = await fetch(`${origin}/api/shop/library`, {
      method: 'GET',
      credentials: 'include',
      headers: { Accept: 'application/json' },
    });

    if (res.status === 404) {
      res = await fetch(`${origin}/shop/library`, {
        method: 'GET',
        credentials: 'include',
        headers: { Accept: 'application/json' },
      });
    }

    if (!res.ok) return [];
    const data = await res.json();
    return data?.entitlements || [];
  },
};

export type CheckoutSubmissionOutcome =
  | {
      type: 'REDIRECTED';
      orderId?: string;
      paymentId: string;
      redirect: string;
      totalAmount: number;
      currency: string;
      idempotencyKey: string;
    }
  | {
      type: 'RECOVERED_STATUS';
      payment: PaymentRecord;
      order?: OrderRecord;
      idempotencyKey: string;
      conflictCode?: string;
    }
  | {
      type: 'CONFLICT_KEY_REUSED';
      message: string;
      idempotencyKey: string;
    }
  | {
      type: 'OUTCOME_UNKNOWN_NO_ID';
      message: string;
      idempotencyKey: string;
      code: string;
    };

/**
 * Parses item references and quantities from a deterministic cart key if items payload was omitted.
 */
export function parseItemsFromCartKey(cartKey?: string): CheckoutItemPayload[] {
  if (!cartKey) return [{ type: 'product', id: 'catalog-item', quantity: 1 }];
  const [itemsPart] = cartKey.split('#');
  if (!itemsPart) return [{ type: 'product', id: 'catalog-item', quantity: 1 }];
  const tokens = itemsPart.split('|');
  const items: CheckoutItemPayload[] = [];
  for (const t of tokens) {
    const [id, qty] = t.split(':');
    if (id && id.trim()) {
      items.push({
        type: 'product',
        id: id.trim(),
        quantity: Math.max(1, Number(qty) || 1),
      });
    }
  }
  return items.length > 0 ? items : [{ type: 'product', id: 'catalog-item', quantity: 1 }];
}

/**
 * Executes a single idempotent checkout attempt calling POST /api/shop/checkout.
 * Handles `409` checkout conflicts and pending/unknown statuses using returned
 * order/payment IDs to recover status WITHOUT automatically starting another payment.
 */
export async function submitOrRecoverCheckoutPayment(params: {
  cartKey: string;
  items?: CheckoutItemPayload[];
  amount?: number;
  description?: string;
  autoRedirect?: boolean;
}): Promise<CheckoutSubmissionOutcome> {
  const attempt = getOrCreateCheckoutAttempt({
    cartKey: params.cartKey,
    amount: params.amount,
    items: params.items,
    description: params.description,
  });

  const itemsToSubmit: CheckoutItemPayload[] =
    params.items && params.items.length > 0
      ? params.items
      : attempt.items && attempt.items.length > 0
      ? attempt.items
      : parseItemsFromCartKey(params.cartKey);

  try {
    const created = await paymentApi.checkout(itemsToSubmit, attempt.idempotencyKey);

    updateStoredCheckoutAttempt({
      orderId: created.orderId,
      paymentId: created.paymentId,
      lastStatus: 'REDIRECTED',
      amount: created.totalAmount,
    });

    if (params.autoRedirect !== false) {
      paymentNavigation.redirectToGateway(created.redirect);
    }

    return {
      type: 'REDIRECTED',
      orderId: created.orderId,
      paymentId: created.paymentId,
      redirect: created.redirect,
      totalAmount: created.totalAmount,
      currency: created.currency,
      idempotencyKey: attempt.idempotencyKey,
    };
  } catch (err) {
    if (err instanceof PaymentApiError && err.status === 409) {
      const conflictCode = err.code as PaymentConflictCode | undefined;
      const recoveryPaymentId = err.paymentId || attempt.paymentId;
      const recoveryOrderId = err.orderId || attempt.orderId;

      if (conflictCode === 'IDEMPOTENCY_KEY_REUSED') {
        return {
          type: 'CONFLICT_KEY_REUSED',
          message:
            err.message ||
            'The checkout attempt data changed since this attempt started. Please start a fresh attempt.',
          idempotencyKey: attempt.idempotencyKey,
        };
      }

      // Recover status using the returned payment ID WITHOUT starting another payment automatically
      if (recoveryPaymentId) {
        updateStoredCheckoutAttempt({
          paymentId: recoveryPaymentId,
          orderId: recoveryOrderId,
        });

        const statusRes = await paymentApi.getPaymentStatus(recoveryPaymentId);
        const payment = statusRes.payment;
        updateStoredCheckoutAttempt({
          paymentId: payment.paymentId,
          orderId: payment.orderId || recoveryOrderId,
          lastStatus: payment.status,
        });

        let order: OrderRecord | undefined = undefined;
        const targetOrderId = payment.orderId || recoveryOrderId;
        if (targetOrderId) {
          try {
            order = await paymentApi.getOrder(targetOrderId);
          } catch {}
        }

        return {
          type: 'RECOVERED_STATUS',
          payment,
          order,
          idempotencyKey: attempt.idempotencyKey,
          conflictCode,
        };
      }

      // Recover status using the returned order ID WITHOUT starting another payment automatically
      if (recoveryOrderId) {
        updateStoredCheckoutAttempt({ orderId: recoveryOrderId });
        try {
          const order = await paymentApi.getOrder(recoveryOrderId);
          return {
            type: 'RECOVERED_STATUS',
            payment: {
              paymentId: recoveryPaymentId || attempt.paymentId || '',
              orderId: recoveryOrderId,
              amount: order.totalAmount,
              currency: order.currency,
              status: order.status === 'PAID' ? 'VERIFIED' : 'VERIFY_PENDING',
            },
            order,
            idempotencyKey: attempt.idempotencyKey,
            conflictCode,
          };
        } catch {}
      }

      return {
        type: 'OUTCOME_UNKNOWN_NO_ID',
        message:
          err.message ||
          'A checkout attempt with this key is already in progress. Please wait before retrying.',
        idempotencyKey: attempt.idempotencyKey,
        code: conflictCode || 'CONFLICT',
      };
    }

    throw err;
  }
}
